const uint8_t* bytes = reinterpret_cast<const uint8_t*>(data);

// Process 8 bytes at a time
while (n >= 8) {
    uint32_t a = crc ^ bytes[0] ^ (bytes[1] << 8) ^ (bytes[2] << 16) ^ (bytes[3] << 24);
    uint32_t b = bytes[4] ^ (bytes[5] << 8) ^ (bytes[6] << 16) ^ (bytes[7] << 24);

    crc = kStrideExtensionTable0[a & 0xFF] ^
          kStrideExtensionTable1[(a >> 8) & 0xFF] ^
          kStrideExtensionTable0[(a >> 16) & 0xFF] ^
          kStrideExtensionTable1[(a >> 24) & 0xFF] ^
          kStrideExtensionTable0[b & 0xFF] ^
          kStrideExtensionTable1[(b >> 8) & 0xFF] ^
          kStrideExtensionTable0[(b >> 16) & 0xFF] ^
          kStrideExtensionTable1[(b >> 24) & 0xFF];

    bytes += 8;
    n -= 8;
}

// Process remaining bytes
while (n > 0) {
    crc = kByteExtensionTable[(crc ^ *bytes) & 0xFF] ^ (crc >> 8);
    bytes++;
    n--;
}

return crc;

